diff --git a/apps/game/src/StationBoard.tsx b/apps/game/src/StationBoard.tsx
--- a/apps/game/src/StationBoard.tsx
+++ b/apps/game/src/StationBoard.tsx
@@ -26,6 +26,38 @@ type MetroLine = {
   closed: boolean;
 };

+/** Estados del tren: Sin tren, En movimiento, Detenido (2 s en una estación). */
+type TrainState = "Sin tren" | "En movimiento" | "Detenido";
+
+type Train = {
+  lineId: string;
+  label: string; // Línea 1 → T1
+  state: TrainState;
+};
+
+/** Velocidad fija igual para todos (~50 px/s), por tiempo real. */
+const TRAIN_SPEED_PX_PER_SECOND = 50;
+/** Detenido 2 s en cada estación. */
+const STOP_DURATION_MS = 2000;
+/** Verde fosforescente mientras un tren pasa o está detenido; se apaga en ~0.8 s. */
+const STATION_GLOW = "#39FF14";
+const LIGHT_FADE_DURATION_MS = 800;
+
+// Asignar tren: aparece en la primera estación y sale de inmediato, sin parada inicial.
+// Línea abierta: va de un extremo al otro y regresa. Circuito: una sola dirección.
+function assignTrain(_lineId: string): void {}
+
+// Retirar tren con el botón "Retirar tren" o tocando el tren.
+function retireTrain(_lineId: string): void {}
+
+// Al extender o cerrar una línea con tren, el tren reinicia desde la primera estación.
+function restartTrain(_train: Train): void {}
+
+export const TRAIN_RULES = { TRAIN_SPEED_PX_PER_SECOND, STOP_DURATION_MS, STATION_GLOW, LIGHT_FADE_DURATION_MS };
+export const TRAIN_ACTIONS = { assignTrain, retireTrain, restartTrain };
+
 const VIEW_W = 400;
 const VIEW_H = 300;
 const VIEW_BOX = `0 0 ${VIEW_W} ${VIEW_H}`;
@@ -420,6 +452,10 @@ export function StationBoard() {
         </Svg>
       </View>
+      {/* Panel "Trenes" bajo el tablero: una fila por línea con "Línea N" y su estado. */}
+      <View accessibilityLabel="Panel Trenes">
+        <Text>Trenes</Text>
+      </View>
       {toast ? <Text style={styles.toast}>{toast}</Text> : null}
     </View>
   );
